-- One month of the ad-free, Premium, bundle or heavy-user plan paid once through WeChat Pay
-- (Stripe cannot put WeChat Pay on a subscription). One row per paid Checkout
-- session: "stripeSessionId" is unique so a repeated webhook counts once, and
-- a second purchase starts where the first ends. "reminderSentDateTime" is the
-- claim that keeps the "ends in 3 days" email to one however many servers see it due.

CREATE TABLE "PrepaidPlan" (
  "id"                   integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "userId"               integer NOT NULL REFERENCES "User" ("id") ON DELETE CASCADE,
  "plan"                 varchar(8) NOT NULL CHECK ("plan" IN ('adfree', 'premium', 'bundle', 'heavy')),
  "stripeSessionId"      varchar(255) NOT NULL UNIQUE,
  "utcStartDateTime"     timestamptz NOT NULL,
  "utcEndDateTime"       timestamptz NOT NULL,
  "reminderSentDateTime" timestamptz,
  "utcCreatedDateTime"   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX "IX_PrepaidPlan_user" ON "PrepaidPlan" ("userId", "utcEndDateTime");
CREATE INDEX "IX_PrepaidPlan_reminder" ON "PrepaidPlan" ("utcEndDateTime") WHERE "reminderSentDateTime" IS NULL;
